pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(100, "", ""); }
    function testRegression_property() public {
        uint256 initialSupply = 100;
        uint256 burnAmount = 40;
        c.burn(burnAmount);
        assertTrue(c.balanceOf(address(this)) == initialSupply - burnAmount);
    }
}
